def semver_sort(versions):
    def parse_key(v):
        # Strip build metadata
        main_and_pre = v.split('+', 1)[0]

        if '-' in main_and_pre:
            core, pre = main_and_pre.split('-', 1)
        else:
            core, pre = main_and_pre, None

        major, minor, patch = (int(x) for x in core.split('.'))

        if pre is not None:
            has_pre = 0
            idents = []
            for ident in pre.split('.'):
                if ident.isdigit():
                    idents.append((0, int(ident)))
                else:
                    idents.append((1, ident))
            pre_tuple = tuple(idents)
        else:
            has_pre = 1
            pre_tuple = ()

        return (major, minor, patch, has_pre, pre_tuple)

    return sorted(versions, key=parse_key)

